import javax.crypto.*;
import javax.crypto.spec.*;
import java.io.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class SecureObjectStore {
    private static final int GCM_IV_LENGTH = 12;
    private static final int GCM_TAG_LENGTH_BITS = 128;

    private final SecretKey encryptionKey;
    private final ConcurrentHashMap<String, byte[]> store;
    private final ReentrantLock serializationLock;
    private final ThreadLocal<Set<String>> activeDeserializations;
    private final Map<String, ObjectResolver> resolvers;

    public SecureObjectStore(byte[] keyMaterial) throws Exception {
        this.encryptionKey = new SecretKeySpec(keyMaterial, "AES");
        this.store = new ConcurrentHashMap<>();
        this.serializationLock = new ReentrantLock();
        this.activeDeserializations = ThreadLocal.withInitial(HashSet::new);
        this.resolvers = new ConcurrentHashMap<>();
    }

    public void registerResolver(String className, ObjectResolver resolver) {
        resolvers.put(className, resolver);
    }

    public void storeObject(String key, Serializable obj) throws Exception {
        serializationLock.lock();
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(obj);
            oos.close();
            byte[] encrypted = encrypt(baos.toByteArray());
            store.put(key, encrypted);
        } finally {
            serializationLock.unlock();
        }
    }

    public Object retrieveObject(String key) throws Exception {
        byte[] encrypted = store.get(key);
        if (encrypted == null) return null;

        Set<String> active = activeDeserializations.get();
        if (active.contains(key)) {
            // Reentrancy detected - refuse to proceed
            throw new SecurityException("Reentrant deserialization blocked for key: " + key);
        }

        active.add(key);
        try {
            byte[] decrypted = decrypt(encrypted);
            return deserializeWithResolvers(decrypted, key);
        } finally {
            active.remove(key);
        }
    }

    private Object deserializeWithResolvers(byte[] data, String contextKey) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ResolvingObjectInputStream(bais, contextKey);
        return ois.readObject();
    }

    private class ResolvingObjectInputStream extends ObjectInputStream {
        private final String contextKey;

        ResolvingObjectInputStream(InputStream in, String contextKey) throws IOException {
            super(in);
            this.contextKey = contextKey;
            enableResolveObject(true);
        }

        @Override
        protected Object resolveObject(Object obj) throws IOException {
            if (obj instanceof ObjectReference) {
                ObjectReference ref = (ObjectReference) obj;
                try {
                    // This triggers reentrant retrieval - will be blocked
                    return retrieveObject(ref.getTargetKey());
                } catch (SecurityException e) {
                    throw new IOException("Circular reference blocked", e);
                } catch (Exception e) {
                    throw new IOException("Resolution failed", e);
                }
            }
            String className = obj.getClass().getName();
            ObjectResolver resolver = resolvers.get(className);
            if (resolver != null) {
                return resolver.resolve(obj, SecureObjectStore.this);
            }
            return obj;
        }
    }

    private byte[] encrypt(byte[] plaintext) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[GCM_IV_LENGTH];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv));
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private byte[] decrypt(byte[] data) throws Exception {
        byte[] iv = Arrays.copyOfRange(data, 0, GCM_IV_LENGTH);
        byte[] ciphertext = Arrays.copyOfRange(data, GCM_IV_LENGTH, data.length);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, encryptionKey, new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv));
        return cipher.doFinal(ciphertext);
    }

    public interface ObjectResolver {
        Object resolve(Object obj, SecureObjectStore store) throws IOException;
    }

    public static class ObjectReference implements Serializable {
        private static final long serialVersionUID = 1L;
        private final String targetKey;
        public ObjectReference(String targetKey) { this.targetKey = targetKey; }
        public String getTargetKey() { return targetKey; }
    }
}
